import { getTableColumns, getTableName } from 'drizzle-orm'
import { getTableConfig, type PgTable } from 'drizzle-orm/pg-core'
import { journalTables } from '../src/journal/tables'

const pgPath = 'drizzle/0078_journal_changes.sql'
const d1Path = 'drizzle-d1/0006_journal_changes.sql'
const marker =
  '-- Journal synchronization revision tracking. Generated by scripts/generate-journal-sync-triggers.ts.'
const tables = journalTables.map((table) => getTableName(table))
/** Primary key columns other than the owner, which identify a changed row. */
const rowKeys = new Map(
  journalTables.map((table) => {
    const single = Object.values(getTableColumns(table))
      .filter((column) => column.primary)
      .map((column) => column.name)
    const composite =
      getTableConfig(table as PgTable).primaryKeys[0]?.columns.map(
        (column) => column.name,
      ) ?? []
    const key = (single.length ? single : composite).filter(
      (name) => name !== 'owner_id',
    )
    if (!key.length) throw new Error(`${getTableName(table)} has no row key`)
    return [getTableName(table), key]
  }),
)
const policies = [
  'journal_sync_revisions',
  'journal_command_receipts',
  'journal_id_reservations',
  'journal_changes',
]
  .map(
    (table) => `
ALTER TABLE "${table}" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "${table}" FORCE ROW LEVEL SECURITY;
CREATE POLICY journal_owner ON "${table}" TO roastbook_journal USING (owner_id = nullif(current_setting('roastbook.user_id', true), '')) WITH CHECK (owner_id = nullif(current_setting('roastbook.user_id', true), ''));
GRANT SELECT, INSERT, UPDATE, DELETE ON "${table}" TO roastbook_journal;
CREATE POLICY instance_control ON "${table}" TO CURRENT_USER USING (true) WITH CHECK (true);
`,
  )
  .join('\n--> statement-breakpoint\n')
const pg = `${marker}\n${policies}
--> statement-breakpoint
CREATE FUNCTION journal_changed() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE source jsonb; journal_owner text; next_revision bigint; changed_key jsonb;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  IF TG_OP = 'DELETE' THEN source := to_jsonb(OLD); ELSE source := to_jsonb(NEW); END IF;
  journal_owner := source->>'owner_id';
  INSERT INTO journal_sync_revisions (owner_id, value) VALUES (journal_owner, 1)
  ON CONFLICT (owner_id) DO UPDATE SET value = journal_sync_revisions.value + 1
  RETURNING value INTO next_revision;
  SELECT jsonb_object_agg(key_column, source->key_column) INTO changed_key FROM unnest(TG_ARGV) AS key_column;
  INSERT INTO journal_changes (owner_id, table_name, row_key, revision)
  VALUES (journal_owner, TG_TABLE_NAME, changed_key::text, next_revision)
  ON CONFLICT (owner_id, table_name, row_key) DO UPDATE SET revision = excluded.revision;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
${tables
  .map(
    (table) =>
      `--> statement-breakpoint\nCREATE TRIGGER journal_changed AFTER INSERT OR UPDATE OR DELETE ON "${table}" FOR EACH ROW EXECUTE FUNCTION journal_changed(${rowKeys
        .get(table)
        ?.map((column) => `'${column}'`)
        .join(', ')});`,
  )
  .join('\n')}
`
const activeOwners = [
  'journal_sync_revisions',
  'journal_command_receipts',
  'journal_id_reservations',
  'journal_changes',
]
  .flatMap((table) =>
    ['insert', 'update'].map(
      (
        event,
      ) => `CREATE TRIGGER "${table}_active_owner_${event}" BEFORE ${event.toUpperCase()} ON "${table}"
WHEN NOT EXISTS (SELECT 1 FROM auth_users WHERE id = NEW.owner_id AND deleting_at IS NULL)
BEGIN SELECT RAISE(ABORT, 'Journal owner is unavailable'); END;`,
    ),
  )
  .join('\n--> statement-breakpoint\n')
const d1 = `${marker}\n${activeOwners}\n--> statement-breakpoint\n${tables
  .flatMap((table) =>
    ['insert', 'update', 'delete'].map((event) => {
      const row = event === 'delete' ? 'OLD' : 'NEW'
      const key = (rowKeys.get(table) ?? [])
        .map((column) => `'${column}', ${row}.${column}`)
        .join(', ')
      return `CREATE TRIGGER "${table}_journal_${event}" AFTER ${event.toUpperCase()} ON "${table}"
WHEN EXISTS (SELECT 1 FROM auth_users WHERE id = ${row}.owner_id AND deleting_at IS NULL)
BEGIN
  INSERT INTO journal_sync_revisions (owner_id, value) VALUES (${row}.owner_id, 1)
  ON CONFLICT (owner_id) DO UPDATE SET value = value + 1;
  INSERT INTO journal_changes (owner_id, table_name, row_key, revision)
  VALUES (${row}.owner_id, '${table}', json_object(${key}), (SELECT value FROM journal_sync_revisions WHERE owner_id = ${row}.owner_id))
  ON CONFLICT (owner_id, table_name, row_key) DO UPDATE SET revision = excluded.revision;
END;`
    }),
  )
  .join('\n--> statement-breakpoint\n')}\n`
for (const [path, generated] of [
  [pgPath, pg],
  [d1Path, d1],
]) {
  if (!path || !generated) throw new Error('Invalid trigger output')
  const current = await Bun.file(path).text()
  const base = current
    .split(marker)[0]
    ?.trimEnd()
    .replace(/--> statement-breakpoint$/, '')
    .trimEnd()
  const output = `${base}\n--> statement-breakpoint\n${generated}`
  if (process.argv.includes('--check')) {
    if (current !== output)
      throw new Error(`Journal triggers are stale: ${path}`)
  } else await Bun.write(path, output)
}
